/* testVector for pe1_rsa.c */
struct _rsa_verify_testdata {
    char *title ;

    // Encoding format
    r_hash_encoding_format_t hash_encoding_format;
    // Hash type
    r_hash_primitive_t       hash_primitive;
    // salt length
    uint16_t salt_size_in_bytes;

    // Key : modulus
    char     *p_modulus ;
    uint16_t modulusBits ;
    // Key : e
    char     *p_pub_e ;
    uint16_t pub_eBits ;

    // message
    uint8_t  bin_message[128] ;
    uint16_t messageBytes ;

    // signature
    char  *p_signature ;
    uint16_t signatureBits ;
    char  *p_signature_dec;
};

